def update(self, dt):
    self.pos += self.velocity * dt
    self.rect.center = (round(self.pos.x), round(self.pos.y))

def set_direction(self, x, y):
    direction = pygame.Vector2(x, y)
    if direction.length_squared() > 1:
        direction = direction.normalize()
    self.velocity = direction * PLAYER_SPEED

def shoot(self, name):
    if self.cooldown > 0 or self.hp == 0:
        return None
    self.cooldown = SHOT_INTERVAL
    return Bullet(name, self)

def take_hit(self, damage):
    self.hp = max(0, self.hp - damage)
    if self.hp == 0:
        self.kill()
        return True
    return False

for bullet in self.bullets.sprites():
    hits = pygame.sprite.spritecollide(
        bullet, self.enemies, False)
    if hits:
        enemy = hits[0]
        destroyed = enemy.take_hit(bullet.damage)
        bullet.kill()
        if destroyed:
            self.score += 10

def take_damage(self):
    if self.invulnerable > 0 or self.hp == 0:
        return False
    self.hp -= 1
    self.invulnerable = 0.8
    return True

